#include <fstream>
int main() {
    std::basic_ifstream<char> file("example.txt");
    const std::basic_filebuf<char>* buf = file.rdbuf();
    // Remove constness to obtain a non-const pointer
    std::basic_filebuf<char>* non_const_buf = const_cast<std::basic_filebuf<char>*>(buf);
    // Now, non_const_buf can be used to modify the buffer if necessary
    return 0;
}
